@Component
@Scope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)
class DiscountCalculator {
    private final List<Discount> applied = new ArrayList<>();

    void apply(Discount discount) { applied.add(discount); }
    Money total(Money subtotal) {
        Money result = subtotal;
        for (Discount d : applied) result = d.applyTo(result);
        return result;
    }
}

@Service
class CheckoutService {
    private final DiscountCalculator calculator;

    CheckoutService(DiscountCalculator calculator) { this.calculator = calculator; }

    Money checkout(Cart cart) {
        cart.discounts().forEach(calculator::apply);
        return calculator.total(cart.subtotal());
    }
}

fix.code:
// Cách 1, nên dùng: bỏ state, tính trong biến cục bộ, bean để singleton
@Component
class DiscountCalculator {
    Money total(Money subtotal, List<Discount> discounts) {
        Money result = subtotal;
        for (Discount d : discounts) result = d.applyTo(result);
        return result;
    }
}
// CheckoutService: return calculator.total(cart.subtotal(), cart.discounts());

// Cách 2: thật sự cần object mới mỗi lần thì hỏi container mỗi lần
@Component
@Scope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)
class StatefulDiscountCalculator { /* như bản cũ */ }

@Service
class CheckoutService {
    private final ObjectProvider<StatefulDiscountCalculator> calculators;

    CheckoutService(ObjectProvider<StatefulDiscountCalculator> calculators) {
        this.calculators = calculators;
    }

    Money checkout(Cart cart) {
        var calculator = calculators.getObject();   // object mới cho lần gọi này
        cart.discounts().forEach(calculator::apply);
        return calculator.total(cart.subtotal());
    }
}
